import re

# Read the full superhero.md file
with open('doc/superhero.md', 'r') as f:
    content = f.read()

# Find where each section starts
biometric_start = content.find("The file for the operative Absorbing Man, registered under ID 7, documents his formidable stature")
publisher_start = content.find("With the completion of the demographic audit, this new volume of the Vanguard Registry now focuses on the crucial classifications of publisher affiliation")

# Extract publisher section
publisher_section = content[publisher_start:] if publisher_start > biometric_start else ""

# Parse publisher section entries
pub_entries = {}
current_entry = {}

lines = publisher_section.split('\n')
for line in lines:
    # Look for superhero name and ID
    name_match = re.search(r'The file for ([A-Za-z0-9\s]+?),\s*(?:registered|identified|tracked|cataloged|filed|maintained|documented|on record|classified|designated|listed)', line, re.IGNORECASE)
    if not name_match:
        name_match = re.search(r'Regarding ([A-Za-z0-9\s]+?),\s*(?:whose|the)', line, re.IGNORECASE)
    if not name_match:
        name_match = re.search(r'For ([A-Za-z0-9\s]+?),\s*(?:the|his|her|its)', line, re.IGNORECASE)

    if name_match:
        # Save previous entry if exists
        if current_entry.get('id'):
            pub_entries[current_entry['id']] = current_entry

        current_entry = {'name': name_match.group(1).strip()}

        # Try to get ID from same line
        id_match = re.search(r'(?:ID|identifier|registry number|reference code)\s+(\d+)', line, re.IGNORECASE)
        if id_match:
            current_entry['id'] = int(id_match.group(1))

    # Check for publisher affiliation
    if 'publisher' in line.lower():
        pub_match = re.search(r'publisher.*?(\d+)', line, re.IGNORECASE)
        if pub_match:
            current_entry['publisher_id'] = int(pub_match.group(1))

# Don't forget last entry
if current_entry.get('id'):
    pub_entries[current_entry['id']] = current_entry

print(f"Parsed {len(pub_entries)} entries from publisher section")
for pid, e in list(pub_entries.items())[:10]:
    print(f"ID {pid}: {e}")

